"    private static final byte[] MZ_MAGIC = new byte[]{0x4D, 0x5A};
    private static final byte[] ELF_MAGIC = new byte[]{0x7F, 'E', 'L', 'F'};
    private static final byte[] PDF_MAGIC = new byte[]{0x25, 0x50, 0x44, 0x46};
    private static final byte[] PNG_MAGIC = new byte[]{(byte) 0x89, 0x50, 0x4E, 0x47};
    private static final byte[] JPEG_MAGIC = new byte[]{(byte) 0xFF, (byte) 0xD8, (byte) 0xFF};

    private static boolean matchesMagicBytes(String contentType, byte[] b) {
        if (startsWithBytes(b, MZ_MAGIC) || startsWithBytes(b, ELF_MAGIC)) {
            return false;
        }
        return switch (contentType) {
            case "application/pdf" -> startsWithBytes(b, PDF_MAGIC);
            case "image/png" -> startsWithBytes(b, PNG_MAGIC);
            case "image/jpeg" -> startsWithBytes(b, JPEG_MAGIC);
            case "text/csv" -> !containsNullByte(b);
            default -> false;
        };
    }

    private static boolean startsWithBytes(byte[] data, byte[] prefix) {
        if (data.length < prefix.length) {
            return false;
        }
        for (int i = 0; i < prefix.length; i++) {
            if (data[i] != prefix[i]) {
                return false;
            }
        }
        return true;
    }"

